  /// < Permission denied
  static const int PERIPHERAL_ERROR_PERMISSION_DENIED = -13;

  /// < Device or resource busy
  static const int PERIPHERAL_ERROR_RESOURCE_BUSY = -16;

  /// < Invalid parameter
  static const int PERIPHERAL_ERROR_INVALID_PARAMETER = -22;

  /// < Not supported
  static const int PERIPHERAL_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Unknown error
  static const int PERIPHERAL_ERROR_UNKNOWN = -1073741824;
}

